import React, { Component } from 'react'
import { connect } from 'react-redux'
import {
  Button,
  Select,
  Row,
  Col,
  Form,
  Alert,
  Modal,
  Icon
} from 'antd'
import { injectIntl } from 'react-intl'
import authAction from '../../../redux/auth/actions'
import WhiteLabelGenerateOtpStyleWrapper from './index.style'
import NumericInput from '../../../components/NumericInput'
import validator from '../../../helpers/validator'
import getDocumentReferrer from '../../../helpers/getDocumentReferrer'
import isTrustedDomain from '../../../helpers/isTrustedDomain'
import IntlMessages from '../../../components/utility/intlMessages'
import getAppConfig from '../../../components/utility/getAppConfig'
// temp
import { millisecondToHMS } from '../../../helpers/utility'
import { RESEND_OTP_COUNT_DOWN } from '../../../constants/constants'
import { ERROR_STRINGS } from '../../../constants/lang'

const FormItem = Form.Item
const Option = Select.Option

const {
  login, generateOtp, resetStatus, verifyOtp,
  authVerifyOtp, resendOtpRequest
} = authAction

class WhiteLabelGenerateOtp extends Component {
  constructor (props) {
    super(props)
    this.state = {
      visible: false,
      isFrom: '/',
      countryCode: '62',
      stopwatch: RESEND_OTP_COUNT_DOWN
    }

    this.decrementer = null
    this.resendCount = 0
  }

  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }

  componentWillReceiveProps (nextProps) {
    const locationState = nextProps.history.location.state || {}
    const from = locationState.from || {}
    const fromPathname = from.pathname || from
    if (Object.keys(from).length > 0) {
      this.setState({ isFrom: fromPathname })
    }
  }
  async validateForm () {
    return new Promise(resolve => {
      this.props.form.validateFields((error, values) => {
        resolve(!error)
      })
    })
  }

  componentWillUnmount () {
    // clear the interval as component remove from the dom
    window.sessionStorage.setItem('count', 0)
  }
  handleSubmit = async e => {
    e.preventDefault()
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    const { form } = this.props
    const payload = form.getFieldsValue()
    this.startTimer()
    this.props.resetStatus()
    this.props.generateOtp({
      phone: `${this.state.countryCode}-${payload.mobile_number}`
    })
  }

  handleSubmitVerify = async e => {
    e.preventDefault()
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    const { form, operationId } = this.props
    const payload = form.getFieldsValue()
    this.props.resetStatus()
    const data = {
      operation_id: operationId,
      otp: payload.otp
    }
    this.props.authVerifyOtp({ body: data })
  }

  resendOtp = () => {
    if (this.resendCount < 5) {
      // if count is less than 5 then call send otp with operation id
      this.resendCount = this.resendCount + 1
      window.sessionStorage.setItem('count', this.resendCount)
      const { operationId } = this.state
      this.props.resendOtpRequest({
        operationId,
        mobileNumber: `${this.state.countryCode}-${this.state.value}`
      })
    } else {
      // it count is greater than or equal to 6 then call this with mobile number
      this.resendCount = 0
      window.sessionStorage.setItem('count', 300)
      this.props.resetStatus()
      this.props.generateOtp({
        phone: `${this.state.countryCode}-${this.state.value}`
      })
    }
    this.startTimer()
  }

  msToHMS = ms => {
    return millisecondToHMS(ms)
  }

  startTimer () {
    // If interval exists we clear it
    if (this.decrementer) {
      clearInterval(this.decrementer)
    }
    // Then we decrement stopwatch by 1 every second
    this.decrementer = setInterval(() => {
      let countDown = this.state.stopwatch - 1000
      this.setState({ stopwatch: countDown })
    }, 1000)
  }

  onChange = value => {
    this.setState({ value })
  }

  onChangeOtp = otp => {
    this.props.form.setFieldsValue({ otp })
    this.setState({ otp })
  }

  showModal = () => {
    this.setState({ visible: true })
  }

  handleCancel = e => {
    this.setState({ visible: false })
  }

  back = () => {
    this.props.resetStatus()
  }

  onCountryCodeSelect = e => {
    this.setState({ countryCode: e })
  }

  countryCodeOptions = () => {
    return (
      <Select defaultValue='+62' onSelect={this.onCountryCodeSelect}>
        <Option value='84'>+84</Option>
        <Option value='66'>+66</Option>
        <Option value='62'>+62</Option>
      </Select>
    )
  }

  renderErrorMessage (message) {
    return (
      <Col span={24}>
        <Alert
          message={message}
          description={<IntlMessages id={ERROR_STRINGS.serverError} />}
          type='error'
          showIcon
          style={{ marginTop: '20px' }}
          closable
        />
      </Col>
    )
  }

  generateOtpForm = () => {
    const { getFieldDecorator } = this.props.form
    const { sendPhoneOtpLoading, sendPhoneOtpError, errorMessage, verifyOtpMessage } = this.props
    return (
      <div
        className='otp-box'
        style={{
          float: 'left'
        }}
      >
        <Row className='padded-container'>
          <div className='sub-title'>
            <p>
              <IntlMessages id='Masukkan nomor telepon terdaftar Anda untuk mengajukan klaim' />
            </p>
          </div>
        </Row>
        <div className='otp-info'>
          <p>
            <IntlMessages id='Dapatkan SMS berisi kode OTP lalu Sign In untuk klaim asuransi Anda' />
          </p>
        </div>
        <Form onSubmit={this.handleSubmit} id='phone'>
          <Row>
            <Row className='padded-container'>
              <div className='input-phone'>
                <FormItem style={{
                  width: '100%'
                }}>
                  {
                    getFieldDecorator('mobile_number', {
                      rules: [
                        {
                          required: true,
                          message: (<IntlMessages id='Nomor handphone tidak boleh kosong' />)
                        }, {
                          validator: validator.checkPhone
                        }
                      ]
                    })(
                      <NumericInput
                        className='mobile-number-input'
                        addonBefore={this.countryCodeOptions()}
                        onChange={this.onChange}
                        minLength='9'
                        maxLength='12'
                      />
                    )
                  }
                </FormItem>
              </div>
            </Row>
            <Row className='container-divider' />
            <Row className='padded-container'>
              <div className='btn-otp-container'>
                <Button
                  type='primary'
                  className='button btn-otp'
                  htmlType='submit'
                  loading={!!sendPhoneOtpLoading}
                  disabled={!this.state.value}
                >
                  <IntlMessages id='Kirim OTP' />
                </Button>
              </div>
            </Row>
          </Row>
          <Row className='mobile-help'>
            <Col>
              <div className='help'>
                <p onClick={this.showModal}><IntlMessages id='Butuh Bantuan?' /></p>
              </div>
            </Col>
          </Row>
          <Row className='alert'>
            {
              ((!!errorMessage && !!sendPhoneOtpError) || verifyOtpMessage) &&
              this.renderErrorMessage(errorMessage || verifyOtpMessage)
            }
          </Row>
          <Row className='desktop-help'>
            <Col>
              <div className='help'>
                <p onClick={this.showModal}>
                  <IntlMessages id='Butuh Bantuan?' />
                </p>
              </div>
            </Col>
          </Row>
        </Form>
      </div>
    )
  }

  verifyOtpForm = (phone) => {
    const { getFieldDecorator } = this.props.form
    const {
      sendPhoneOtpLoading,
      verifyOtpMessage,
      verifyAuthOtpError,
      verifyAuthOtpLoading
    } = this.props
    const { value } = this.state
    return (
      <div
        className='otp-box'
        style={{
          float: 'left',
          marginTop: 20
        }}
      >
        <Form onSubmit={this.handleSubmitVerify} id='otp'>
          <div>
            <Row className='padded-container'>
              <Row>
                <div className='input-phone'>
                  <div className='phone-label'>
                    <label>
                      <IntlMessages id='No. Telp' />
                    </label>
                  </div>
                  <FormItem
                    style={{
                      width: '100%'
                    }}
                  >
                    {
                      getFieldDecorator('mobile_number', {
                        rules: [
                          {
                            required: false
                          }
                        ]
                      })(
                        <React.Fragment>
                          <Col sm={24} md={0}>
                            <NumericInput
                              addonBefore={<Icon type='phone' />}
                              onChange={this.onChange}
                              disabled
                              value={value}
                            />
                          </Col>
                          <div className='hide-desktop'>
                            <Col sm={0} md={24}>
                              <NumericInput
                                onChange={this.onChange}
                                disabled
                                value={value}
                              />
                            </Col>
                          </div>
                        </React.Fragment>
                      )
                    }
                  </FormItem>
                </div>
              </Row>
              <Row>
                <div className='input-phone'>
                  <div className='phone-label'>
                    <label>
                      <IntlMessages id='OTP' />
                    </label>
                  </div>
                  <FormItem
                    style={{
                      width: '100%'
                    }}
                  >
                    {
                      getFieldDecorator('otp', {
                        rules: [
                          {
                            required: true,
                            message: (<IntlMessages id='OTP tidak boleh kosong' />)
                          }, {
                            validator: validator.checkOtp
                          }
                        ]
                      })(
                        <React.Fragment>
                          <Col sm={24} md={0}>
                            <NumericInput
                              autoFocus='autoFocus'
                              type='otp'
                              addonBefore={<Icon type='lock' />}
                              onChange={this.onChangeOtp}
                              disabled={false}
                              minLength={6}
                              maxLength={6}
                            />
                          </Col>
                          <div className='hide-desktop'>
                            <Col sm={0} md={24}>
                              <NumericInput
                                autoFocus='autoFocus'
                                type='otp'
                                onChange={this.onChangeOtp}
                                disabled={false}
                                minLength={6}
                                maxLength={6}
                              />
                            </Col>
                          </div>
                        </React.Fragment>
                      )
                    }
                  </FormItem>
                </div>
              </Row>
            </Row>
            <Row className='container-divider' />
            <Row>
              <div className='button-box'>
                <Col span={12}>
                  <Button
                    type='primary'
                    className='otp-button'
                    loading={!!sendPhoneOtpLoading}
                    disabled={this.state.stopwatch > 0}
                    onClick={this.resendOtp}
                  >
                    <IntlMessages id='Kirim ulang OTP' />
                    {this.state.stopwatch > 0 && (
                      <React.Fragment>
                        <br />
                        {this.msToHMS(this.state.stopwatch)}
                      </React.Fragment>
                    )}
                  </Button>
                </Col>
                <Col span={12}>
                  <Button
                    type='primary'
                    className='otp-button'
                    htmlType='submit'
                    loading={!!verifyAuthOtpLoading}
                    disabled={!phone || !this.state.value}
                  >
                    <IntlMessages id='Masuk' />
                  </Button>
                </Col>
                <Col span={24} className='back-button'>
                  <a onClick={() => this.back()}><IntlMessages id='Kembali' /></a>
                  &nbsp;|&nbsp;
                  <a onClick={this.showModal}><IntlMessages id='Butuh Bantuan?' /></a>
                </Col>
                {!!verifyOtpMessage && !!verifyAuthOtpError && this.renderErrorMessage(verifyOtpMessage)}
              </div>
            </Row>
          </div>
        </Form>
      </div>
    )
  }

  redirectionHandler = (from) => {
    const urlObj = getDocumentReferrer()
    if (urlObj.pathname && urlObj.pathname.includes('/endorsement') && isTrustedDomain(urlObj.host)) {
      window.location.href = urlObj.href
    } else {
      from === '/'
        ? window.location.reload()
        : window.history.pushState({}, null, from)
    }
  }

  render () {
    const { isFrom } = this.state
    const { operationId, phone } = this.props
    if (this.props.isLoggedIn) {
      this.redirectionHandler(isFrom)
    }
    return (
      <div>
        <Modal
          title=''
          visible={this.state.visible}
          footer={[
            <Button key='ok' onClick={this.handleCancel}>
              <IntlMessages id='Ok' />
            </Button>
          ]}
          closable={false}
        >
          {/* TODO: Replace with dynamic message */}
          {/* <p>
            <b>
              <IntlMessages id='Nomor telepon yang diisi adalah nomor Anda yang telah terdaftar di GO-LIFE.'/>
            </b>
          </p> */}
          <p>
            <b>
              <IntlMessages id='Jika butuh bantuan lebih lanjut, hubungi CS kami:' />
            </b>
          </p>
          {/* <p>
            <b>Telepon: 021 5089 0580</b>
          </p> */}
          <p>
            <b>Whatsapp: (+62) 818 343 494</b>
          </p>
        </Modal>
        <WhiteLabelGenerateOtpStyleWrapper
          secondaryColor={getAppConfig('SECONDARY_COLOR')}
          highlighterColor={getAppConfig('HIGHLIGHTER_COLOR')}
          fontColor={getAppConfig('FONT_COLOR')}
        >
          <div className='container positionStatic'>

            <Row
              className='content-row'
              style={{
                display: 'flex',
                justifyContent: 'baseline'
              }}
            >
              <Col xl={{ span: 12, offset: 4 }} className='container-col'>
                <Row
                  style={{
                    marginTop: '-5px'
                  }}
                >
                  <Col span={24} md={0} className='hero-title-main'>
                    <p
                      style={{
                        marginBottom: 5
                      }}
                    >
                      {this.intlText({ id: 'AJUKAN KLAIM' })}
                    </p>
                  </Col>
                  <Col span={24} md={0} className='hero-title'>
                    <p>{this.intlText({ id: ' Proses klaim anti ribet langsung dari smartphone. Kami selalu siap membantumu.' })}</p>
                  </Col>
                </Row>
                <Row>
                  <Col span={0} md={24}>
                    <div className='hero-title-golife'>
                      <p className='title-text'>
                        <IntlMessages id='Kami turut bersimpati atas musibah' />{' '}
                        <br />
                        <IntlMessages id=' yang Anda alami.' />
                      </p>
                    </div>
                  </Col>
                </Row>
                {
                  !operationId ? this.generateOtpForm() : this.verifyOtpForm(phone)
                }
              </Col>
            </Row>
          </div>
        </WhiteLabelGenerateOtpStyleWrapper>
      </div>
    )
  }
}
const WrappedWhiteLabelGenerateOtpForm = Form.create()(WhiteLabelGenerateOtp)
export default connect(state => ({
  isLoggedIn: state.Auth.idToken !== null,
  operationId: state.Auth.operationId,
  phone: state.Auth.phone,
  errorMessage: state.Auth.errorMessage,
  verifyOtpFailedStatus: state.Auth.verifyOtpFailedStatus,
  sendPhoneOtpLoading: state.Loading.GENERATE_OTP,
  sendPhoneOtpError: state.Error.GENERATE_OTP,
  verifyOtpMessage: state.Auth.verifyOtpMessage,
  verifyAuthOtpLoading: state.Loading.AUTH_VERIFY_OTP,
  verifyAuthOtpError: state.Error.AUTH_VERIFY_OTP
}), {
  login,
  generateOtp,
  resetStatus,
  verifyOtp,
  authVerifyOtp,
  resendOtpRequest
})(injectIntl(WrappedWhiteLabelGenerateOtpForm))
